from decimal import Decimal, ROUND_HALF_UP, InvalidOperation

Q=Decimal('0.01')
def r(x):
    return x.quantize(Q, rounding=ROUND_HALF_UP)

BULK=50
TAX={'NZ':Decimal('0.15'),'US':Decimal('0')}
TIER={'platinum':Decimal('0.10'),'gold':Decimal('0.08'),'silver':Decimal('0.02')}

def _validate(lines):
    if not lines:
        raise ValueError('empty lines')
    for l in lines:
        q=l.get('qty')
        if isinstance(q,bool) or not isinstance(q,int) or q<0:
            raise ValueError('bad qty')
        try:
            p=Decimal(str(l.get('unit_price')))
        except (InvalidOperation,TypeError):
            raise ValueError('bad price')
        if not p.is_finite() or p<0:
            raise ValueError('bad price')

def compute_invoice(lines, customer):
    _validate(lines)
    lines=[l for l in lines if l['qty']>0]
    if not lines:
        raise ValueError('all ignored')
    amts=[r(l['qty']*Decimal(str(l['unit_price']))*(Decimal('0.90') if l['qty']>=BULK else 1)) for l in lines]
    subtotal=sum(amts,Decimal('0'))
    elig=sum((a for a,l in zip(amts,lines) if l['qty']<BULK),Decimal('0'))
    discount=r(TIER.get(customer.get('tier'),Decimal('0'))*elig)
    c=customer.get('coupon')
    c=Decimal(str(c)) if c not in (None,'') else Decimal('0')
    discount=discount+r(max(Decimal('0'),min(c,subtotal-discount)))
    net=subtotal-discount
    shipping=Decimal('7.50') if net<Decimal('100.00') else Decimal('0')
    tax=r((net+shipping)*TAX.get(customer.get('region'),Decimal('0.10')))
    total=net+shipping+tax
    return {k:str(r(v)) for k,v in [('subtotal',subtotal),('discount',discount),('shipping',shipping),('tax',tax),('total',total)]}

